Source code in <code>nmr/types/tune.py</code> <pre><code>def duration_value(index: int, sounding: bool = False) -&gt; Fraction:
    if index &lt; 0:
        raise ValueError("Expected a nonnegative duration index")
    kind = "note_duration_starts" if sounding else "duration_starts"
    layers = tune_count.tune_counts(MAX_COST)[kind]
    if index &gt;= layers[MAX_WEIGHT + 1]:
        raise ValueError("Tune work limit: duration weight exceeds 512")
    lower, upper = (
        0,
        min(MAX_WEIGHT + 1, tune_count.NUMERATOR_COST * (index + 1).bit_length() + 1),
    )
    while upper - lower &gt; 1:
        middle = (lower + upper) // 2
        if layers[middle] &lt;= index:
            lower = middle
        else:
            upper = middle
    weight = lower
    index -= layers[weight]
    for h in range(weight // tune_count.NUMERATOR_COST + 1):
        for b in (0, 1):
            a, remainder = divmod(
                weight - tune_count.NUMERATOR_COST * h - tune_count.THIRD_COST * b,
                tune_count.BINARY_COST,
            )
            if a &lt; 0 or remainder:
                continue
            start, end = 1 &lt;&lt; h, (1 &lt;&lt; (h + 1)) - 1
            count = group_count(start, end, a, b, sounding)
            if index &gt;= count:
                index -= count
                continue
            lower, upper = start - 1, end
            while upper - lower &gt; 1:
                middle = (lower + upper) // 2
                if group_count(start, middle, a, b, sounding) &lt;= index:
                    lower = middle
                else:
                    upper = middle
            return Fraction(upper, (1 &lt;&lt; a) * 3**b)
    raise AssertionError("Duration index has no group")
